import base64

def replace_arquivo_inteiro(caminho, old_b64, new_b64, label):
    with open(caminho, 'r', encoding='utf-8') as f:
        atual = f.read()
    esperado = base64.b64decode(old_b64).decode('utf-8')
    novo = base64.b64decode(new_b64).decode('utf-8')
    if atual != esperado:
        raise SystemExit(f'[{label}] O conteudo atual de {caminho} nao bate com o esperado. Abortando sem alterar nada. Rode git status e me avise.')
    with open(caminho, 'w', encoding='utf-8') as f:
        f.write(novo)
    print(f'[{label}] OK - {caminho} atualizado.')

replace_arquivo_inteiro(
    'src/main.tsx',
    '',
    '',
    'src/main.tsx',
)

print('\nTela Espiritual atualizada com sucesso (ajuste visual).')
